20.         ["δέκα", "έντεκα", "δώδεκα", "δεκατρία", "δεκατέσσερα", "δεκαπέντε", "δεκαέξι", "δεκαεφτά", "δεκαοκτώ", "δεκαεννιά"];
21. 
22.     private static readonly string[] HundredMap =
23.         ["", "εκατό", "διακόσια", "τριακόσια", "τετρακόσια", "πεντακόσια", "εξακόσια", "εφτακόσια", "οκτακόσια", "εννιακόσια"];
