[assembly: CollectionBehavior(DisableTestParallelization = true)]

namespace ContosoUniversity.Tests
{
    /// <summary>
    /// Shared helpers for creating in-memory EF Core contexts and wiring up
    /// controllers with the minimal ASP.NET Core plumbing the actions need.
    /// </summary>
    internal static class TestSupport
    {
        public static SchoolContext CreateContext(string databaseName = null)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName ?? Guid.NewGuid().ToString())
                .EnableSensitiveDataLogging()
                .Options;
            return new SchoolContext(options);
        }

        /// <summary>
        /// Attaches an HttpContext + TempData to a controller so actions that
        /// use TempData or RequestServices do not throw.
        /// </summary>
        public static void PrepareController(Controller controller, IServiceProvider services = null)
        {
            var httpContext = new DefaultHttpContext();
            if (services != null)
            {
                httpContext.RequestServices = services;
            }

            controller.ControllerContext = new ControllerContext
            {
                HttpContext = httpContext
            };
            controller.TempData = new TempDataDictionary(httpContext, Mock.Of<ITempDataProvider>());
        }

        private static IServiceProvider _mvcServices;

        /// <summary>
        /// Builds a real MVC service provider so that model-binding APIs such as
        /// TryUpdateModelAsync can resolve their dependencies.
        /// </summary>
        public static IServiceProvider MvcServices()
        {
            if (_mvcServices != null)
            {
                return _mvcServices;
            }

            var services = new ServiceCollection();
            services.AddSingleton<DiagnosticSource>(new DiagnosticListener("test"));
            services.AddSingleton(new DiagnosticListener("test"));
            services.AddLogging();
            services.AddMvcCore().AddDataAnnotations();
            _mvcServices = services.BuildServiceProvider();
            return _mvcServices;
        }

        /// <summary>Empties the shared notification queue.</summary>
        public static void DrainNotifications()
        {
            using var service = new NotificationService();
            while (service.ReceiveNotification() != null)
            {
            }
        }

        public static object GetAnonymousProperty(object source, string name)
        {
            return source.GetType().GetProperty(name)?.GetValue(source);
        }
    }
