{"file_text":"using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests
{
    [Collection("NotificationQueue")]
    public class NotificationServiceTests
    {
        public NotificationServiceTests()
        {
            TestSupport.DrainNotifications();
        }

        [Fact]
        public void SendReceive_PreservesFifoOrder()
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "1", EntityOperation.CREATE);
            service.SendNotification("Student", "2", EntityOperation.DELETE);

            var first = service.ReceiveNotification();
            var second = service.ReceiveNotification();

            Assert.Equal("1", first.EntityId);
            Assert.Equal("2", second.EntityId);
            Assert.Null(service.ReceiveNotification());
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            using var service = new NotificationService();

            Assert.Null(service.ReceiveNotification());
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "Course", "42", null, "New Course (ID: 42) has been created")]
        [InlineData(EntityOperation.CREATE, "Course", "42", "Chemistry", "New Course 'Chemistry' has been created")]
        [InlineData(EntityOperation.UPDATE, "Course", "42", "Chemistry", "Course 'Chemistry' has been updated")]
        [InlineData(EntityOperation.UPDATE, "Course", "42", null, "Course (ID: 42) has been updated")]
        [InlineData(EntityOperation.DELETE, "Course", "42", "Chemistry", "Course 'Chemistry' has been deleted")]
        [InlineData(EntityOperation.DELETE, "Course", "42", "   ", "Course (ID: 42) has been deleted")]
        public void SendNotification_GeneratesExpectedMessage(
            EntityOperation operation, string type, string id, string displayName, string expectedMessage)
        {
            using var service = new NotificationService();

            service.SendNotification(type, id, displayName, operation);
            var notification = service.ReceiveNotification();

            Assert.Equal(expectedMessage, notification.Message);
            Assert.Equal(operation.ToString(), notification.Operation);
            Assert.Equal(type, notification.EntityType);
            Assert.Equal(id, notification.EntityId);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_DefaultsCreatedByToSystem()
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "1", EntityOperation.CREATE);

            Assert.Equal("System", service.ReceiveNotification().CreatedBy);
        }

        [Fact]
        public void SendNotification_UsesProvidedUserName()
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "1", null, EntityOperation.CREATE, "alice");

            Assert.Equal("alice", service.ReceiveNotification().CreatedBy);
        }

        [Fact]
        public void SendNotification_EnforcesMaxQueueLength()
        {
            using var service = new NotificationService();

            for (int i = 0; i < 600; i++)
            {
                service.SendNotification("Student", i.ToString(), EntityOperation.CREATE);
            }

            int drained = 0;
            while (service.ReceiveNotification() != null)
            {
                drained++;
            }

            Assert.Equal(500, drained);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            using var service = new NotificationService();

            var exception = Record.Exception(() => service.MarkAsRead(1));

            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();

            var exception = Record.Exception(() => service.Dispose());

            Assert.Null(exception);
        }
    }
}
