            var result = Assert.IsType<RedirectToActionResult>(controller.DeleteConfirmed(instructor.ID));

            Assert.Equal("Index", result.ActionName);
            Assert.DoesNotContain(context.Instructors, i => i.ID == instructor.ID);
            Assert.Null(context.Departments.Single(d => d.DepartmentID == department.DepartmentID).InstructorID);
            using var notifier = new NotificationService();
            Assert.Equal("DELETE", notifier.ReceiveNotification().Operation);
        }
    }
