        public TestableInstructorsController(SchoolContext context) : base(context) { }

        public async Task<string> DoEdit(int id, string[] selectedCourses)
        {
            var sb = new StringBuilder();
            var instructorToUpdate = db.Instructors
               .Include(i => i.OfficeAssignment)
               .Include(i => i.CourseAssignments)
                   .ThenInclude(c => c.Course)
               .Single(i => i.ID == id);

            bool bound = await TryUpdateModelAsync<Instructor>(instructorToUpdate, "",
                i => i.LastName, i => i.FirstMidName, i => i.HireDate, i => i.OfficeAssignment);
            sb.AppendLine("BOUND=" + bound);
            sb.AppendLine("OfficeNull=" + (instructorToUpdate.OfficeAssignment == null));
            try
            {
                if (string.IsNullOrWhiteSpace(instructorToUpdate.OfficeAssignment?.Location))
                {
                    instructorToUpdate.OfficeAssignment = null;
                }
                db.SaveChanges();
                sb.AppendLine("SAVE OK");
            }
            catch (Exception ex)
            {
                sb.AppendLine("EX=" + ex.GetType().FullName + " : " + ex.Message);
                if (ex.InnerException != null) sb.AppendLine("INNER=" + ex.InnerException.Message);
            }
            return sb.ToString();
        }
    }

