        public static void PrepareControllerWithForm(Controller controller, Dictionary<string, Microsoft.Extensions.Primitives.StringValues> form)
        {
            var httpContext = new DefaultHttpContext
            {
                RequestServices = MvcServices()
            };
            httpContext.Request.ContentType = "application/x-www-form-urlencoded";
            httpContext.Request.Form = new FormCollection(form);

            controller.ControllerContext = new ControllerContext
            {
                HttpContext = httpContext
            };
            controller.ControllerContext.ValueProviderFactories.Add(new Microsoft.AspNetCore.Mvc.ModelBinding.FormValueProviderFactory());
