from __future__ import annotations

from datetime import timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTag:
    @pytest.mark.parametrize(
        "raw,expected",
        [
            ("Work", "work"),
            ("  Home  ", "home"),
            ("URGENT", "urgent"),
            ("side-project", "side-project"),
            ("has_underscore", "has_underscore"),
            ("abc123", "abc123"),
            ("a" * 32, "a" * 32),  # boundary: exactly 32 chars is allowed
        ],
    )
    def test_normalizes_name(self, raw, expected):
        assert Tag(raw).name == expected

    @pytest.mark.parametrize("raw", ["", "   ", "\t\n"])
    def test_empty_after_strip_raises(self, raw):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag(raw)

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters or fewer"):
            Tag("a" * 33)

    @pytest.mark.parametrize("raw", ["has space", "excl!", "comma,", "slash/", "dot."])
    def test_illegal_character_raises(self, raw):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(raw)

    @pytest.mark.parametrize("raw", [123, None, ["work"]])
    def test_non_string_raises_type_error(self, raw):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(raw)


class TestTaskPriorityOrder:
    def test_order_key_high_before_low(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(
            TaskPriority.MEDIUM
        )
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(
            TaskPriority.LOW
        )

    def test_order_key_exact_values(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) == 0
        assert TaskPriority.order_key(TaskPriority.MEDIUM) == 1
        assert TaskPriority.order_key(TaskPriority.LOW) == 2


class TestTaskIsOverdue:
    def test_no_due_date_is_not_overdue(self, fixed_now):
        task = Task(id=1, title="t", due_at=None)
        assert task.is_overdue(fixed_now) is False

    def test_done_task_is_never_overdue(self, fixed_now):
        past = fixed_now - timedelta(hours=1)
        task = Task(id=1, title="t", status=TaskStatus.DONE, due_at=past)
        assert task.is_overdue(fixed_now) is False

    def test_past_due_and_pending_is_overdue(self, fixed_now):
        past = fixed_now - timedelta(seconds=1)
        task = Task(id=1, title="t", due_at=past)
        assert task.is_overdue(fixed_now) is True

    def test_future_due_is_not_overdue(self, fixed_now):
        future = fixed_now + timedelta(seconds=1)
        task = Task(id=1, title="t", due_at=future)
        assert task.is_overdue(fixed_now) is False

    def test_due_exactly_now_is_not_overdue(self, fixed_now):
        # Boundary: strictly-less-than, so due == now is not overdue.
        task = Task(id=1, title="t", due_at=fixed_now)
        assert task.is_overdue(fixed_now) is False

    def test_default_created_at_is_timezone_aware(self):
        task = Task(id=1, title="t")
        assert task.created_at.tzinfo is not None
