{"file_text":""""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag
from tasks_api.repository import InMemoryTaskRepository, normalize_tags

from conftest import make_task


class TestInMemoryTaskRepository:
    def test_add_and_get(self, repository):
        task = make_task(1, "a")
        repository.add(task)
        assert repository.get(1) is task

    def test_get_missing_returns_none(self, repository):
        assert repository.get(999) is None

    def test_add_duplicate_id_raises(self, repository):
        repository.add(make_task(1))
        with pytest.raises(ValueError, match="already exists"):
            repository.add(make_task(1))

    def test_list_returns_all(self, repository):
        repository.add(make_task(1))
        repository.add(make_task(2))
        assert {t.id for t in repository.list()} == {1, 2}

    def test_list_returns_snapshot_copy(self, repository):
        repository.add(make_task(1))
        snapshot = repository.list()
        repository.add(make_task(2))
        # The earlier snapshot must not reflect the later insertion.
        assert [t.id for t in snapshot] == [1]

    def test_update_replaces_task(self, repository):
        repository.add(make_task(1, "old"))
        repository.update(make_task(1, "new"))
        assert repository.get(1).title == "new"

    def test_update_missing_raises_key_error(self, repository):
        with pytest.raises(KeyError):
            repository.update(make_task(42))

    def test_delete_existing_returns_true(self, repository):
        repository.add(make_task(1))
        assert repository.delete(1) is True
        assert repository.get(1) is None

    def test_delete_missing_returns_false(self, repository):
        assert repository.delete(1) is False

    def test_next_id_increments(self, repository):
        assert repository.next_id() == 1
        assert repository.next_id() == 2
        assert repository.next_id() == 3


class TestNormalizeTags:
    def test_wraps_strings_into_tags(self):
        result = normalize_tags(["Work", "home"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["work", "home"]

    def test_deduplicates_by_normalized_name(self):
        result = normalize_tags(["Work", "work", "  WORK "])
        assert [t.name for t in result] == ["work"]

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["b", "a", "b", "c"])
        assert [t.name for t in result] == ["b", "a", "c"]

    def test_accepts_tag_instances(self):
        result = normalize_tags([Tag("work"), "home", Tag("work")])
        assert [t.name for t in result] == ["work", "home"]

    def test_empty_iterable(self):
        assert normalize_tags([]) == []
