    "constructor rejects non-negative-integer amount %s",
    (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    },
  );

  it("caps the discount at the subtotal", () => {
    expect(new FixedAmountDiscountPolicy(5000).computeDiscountCents(3000)).toBe(3000);
  });

  it("returns the flat amount when below subtotal", () => {
    expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(3000)).toBe(500);
